    <title>Nocturne Supply | Dark Retail Home</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #07090f;
        --bg-soft: #101521;
        --panel: rgba(19, 25, 39, 0.82);
        --panel-strong: #151c2b;
        --text: #f7f8fb;
        --muted: #b8c0d4;
        --subtle: #7f8aa3;
        --line: rgba(255, 255, 255, 0.12);
        --brand: #9ef01a;
        --brand-2: #22d3ee;
        --accent: #f59e0b;
        --danger: #fb7185;
        --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
        --radius-lg: 28px;
        --radius-md: 20px;
        --radius-sm: 14px;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
      }

      * {
        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        margin: 0;
        min-height: 100vh;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgba(34, 211, 238, 0.24), transparent 31rem),
          radial-gradient(circle at 85% 18%, rgba(158, 240, 26, 0.17), transparent 26rem),
          linear-gradient(180deg, #07090f 0%, #0b101a 46%, #06070b 100%);
      }

      body::before {
        position: fixed;
        inset: 0;
        z-index: -1;
        pointer-events: none;
        content: "";
        background-image:
          linear-gradient(rgba(255, 255, 255, 0.04) 1px, transparent 1px),
          linear-gradient(90deg, rgba(255, 255, 255, 0.04) 1px, transparent 1px);
        background-size: 56px 56px;
        mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 0.7), transparent 75%);
      }

      a {
        color: inherit;
        text-decoration: none;
      }

      a:hover {
        color: var(--brand);
      }

      a:focus-visible,
      button:focus-visible {
        outline: 3px solid var(--brand-2);
        outline-offset: 4px;
      }

      button {
        font: inherit;
      }

      .page-shell {
        width: min(1180px, calc(100% - 32px));
        margin: 0 auto;
      }

      .skip-link {
        position: absolute;
        top: 14px;
        left: 14px;
        z-index: 10;
        padding: 10px 14px;
        color: #06100b;
        background: var(--brand);
        border-radius: 999px;
        transform: translateY(-150%);
        transition: transform 160ms ease;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .site-header {
        position: sticky;
        top: 0;
        z-index: 5;
        border-bottom: 1px solid var(--line);
        backdrop-filter: blur(18px);
        background: rgba(7, 9, 15, 0.74);
      }

      .nav {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 24px;
        min-height: 76px;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 12px;
        font-weight: 850;
        letter-spacing: -0.04em;
      }

      .brand-mark {
        display: grid;
        width: 42px;
        height: 42px;
        color: #081006;
        background: linear-gradient(135deg, var(--brand), var(--brand-2));
        border-radius: 14px;
        box-shadow: 0 0 30px rgba(158, 240, 26, 0.28);
        place-items: center;
      }

      .nav-links {
        display: flex;
        align-items: center;
        gap: 20px;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .nav-actions {
        display: flex;
        align-items: center;
        gap: 12px;
      }

      .pill {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        min-height: 42px;
        padding: 0 16px;
        border: 1px solid var(--line);
        border-radius: 999px;
        background: rgba(255, 255, 255, 0.04);
      }

      .button {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 10px;
        min-height: 48px;
        padding: 0 20px;
        color: #081006;
        font-weight: 800;
        border: 0;
        border-radius: 999px;
        background: linear-gradient(135deg, var(--brand), #d9ff6a);
        box-shadow: 0 16px 38px rgba(158, 240, 26, 0.22);
        cursor: pointer;
      }

      .button.secondary {
        color: var(--text);
        border: 1px solid var(--line);
        background: rgba(255, 255, 255, 0.06);
        box-shadow: none;
      }

      .hero {
        display: grid;
        grid-template-columns: minmax(0, 1.02fr) minmax(320px, 0.98fr);
        gap: 32px;
        align-items: stretch;
        padding: 64px 0 42px;
      }

      .hero-copy {
        padding: clamp(28px, 5vw, 56px);
        border: 1px solid var(--line);
        border-radius: var(--radius-lg);
        background:
          linear-gradient(140deg, rgba(255, 255, 255, 0.09), rgba(255, 255, 255, 0.025)),
          var(--panel);
        box-shadow: var(--shadow);
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        margin: 0 0 18px;
        color: var(--brand);
        font-weight: 800;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        font-size: 0.78rem;
      }

      .eyebrow::before {
        width: 10px;
        height: 10px;
        content: "";
        background: currentColor;
        border-radius: 50%;
        box-shadow: 0 0 22px currentColor;
      }

      h1,
      h2,
      h3 {
        margin: 0;
        letter-spacing: -0.055em;
        line-height: 0.98;
      }

      h1 {
        max-width: 10ch;
        font-size: clamp(3.2rem, 8vw, 7.4rem);
      }

      h2 {
        font-size: clamp(2rem, 4vw, 3.6rem);
      }

      h3 {
        font-size: 1.2rem;
      }

      p {
        line-height: 1.7;
      }

      .hero-copy > p {
        max-width: 62ch;
        margin: 22px 0 28px;
        color: var(--muted);
        font-size: 1.08rem;
      }

      .hero-actions,
      .section-heading {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 18px;
        flex-wrap: wrap;
      }

      .hero-actions {
        justify-content: flex-start;
      }

      .hero-panel {
        position: relative;
        display: grid;
        min-height: 560px;
        overflow: hidden;
        border: 1px solid var(--line);
        border-radius: var(--radius-lg);
        background:
          radial-gradient(circle at 45% 32%, rgba(158, 240, 26, 0.35), transparent 14rem),
          linear-gradient(160deg, #202b3f, #0d111b 62%);
        box-shadow: var(--shadow);
        place-items: end center;
      }

      .hero-product {
        position: relative;
        width: min(76%, 390px);
        height: 72%;
        margin-bottom: 44px;
        border-radius: 38% 38% 22% 22%;
        background:
          linear-gradient(90deg, transparent 42%, rgba(255, 255, 255, 0.16) 43%, transparent 48%),
          linear-gradient(145deg, #1d2638, #0c1019);
        box-shadow:
          inset 0 0 0 1px rgba(255, 255, 255, 0.12),
          0 40px 90px rgba(0, 0, 0, 0.55);
      }

      .hero-product::before,
      .hero-product::after {
        position: absolute;
        content: "";
        border-radius: 999px;
      }

      .hero-product::before {
        top: 11%;
        left: 16%;
        width: 68%;
        height: 24%;
        border: 18px solid rgba(158, 240, 26, 0.8);
        border-bottom-color: transparent;
      }

      .hero-product::after {
        right: 18%;
        bottom: 16%;
        width: 92px;
        height: 92px;
        background: linear-gradient(135deg, var(--brand-2), var(--brand));
        box-shadow: 0 0 42px rgba(34, 211, 238, 0.38);
      }

      .floating-card {
        position: absolute;
        right: 24px;
        bottom: 28px;
        width: min(280px, calc(100% - 48px));
        padding: 18px;
        border: 1px solid var(--line);
        border-radius: 22px;
        background: rgba(7, 9, 15, 0.78);
        backdrop-filter: blur(16px);
      }

      .floating-card strong {
        display: block;
        margin-bottom: 6px;
      }

      .stats {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 14px;
        margin-top: 34px;
      }

      .stat {
        padding: 18px;
        border: 1px solid var(--line);
        border-radius: var(--radius-sm);
        background: rgba(255, 255, 255, 0.04);
      }

      .stat strong {
        display: block;
        font-size: 1.35rem;
      }

      .stat span,
      .kicker,
      .article-meta {
        color: var(--subtle);
        font-size: 0.9rem;
      }

      section {
        padding: 42px 0;
      }

      .section-heading {
        margin-bottom: 24px;
      }

      .section-heading p {
        max-width: 56ch;
        margin: 0;
        color: var(--muted);
      }

      .product-grid,
      .deal-grid,
      .editorial-grid {
        display: grid;
        gap: 18px;
      }

      .product-grid {
        grid-template-columns: repeat(4, minmax(0, 1fr));
      }

      .product-card,
      .deal-card,
      .article-card,
      .newsletter {
        border: 1px solid var(--line);
        border-radius: var(--radius-md);
        background: var(--panel);
        box-shadow: 0 18px 50px rgba(0, 0, 0, 0.24);
      }

      .product-card {
        overflow: hidden;
      }

      .product-art {
        display: grid;
        min-height: 210px;
        margin: 12px;
        border-radius: 18px;
        background:
          radial-gradient(circle at 50% 40%, var(--glow), transparent 7rem),
          linear-gradient(145deg, rgba(255, 255, 255, 0.11), rgba(255, 255, 255, 0.025));
        place-items: center;
      }

      .product-shape {
        width: 46%;
        aspect-ratio: 1;
        border-radius: var(--shape);
        background: linear-gradient(145deg, #f7f8fb, #7f8aa3 70%, #30394e);
        box-shadow:
          inset -12px -16px 28px rgba(0, 0, 0, 0.24),
          0 24px 55px rgba(0, 0, 0, 0.38);
      }

      .product-body,
      .article-body {
        padding: 10px 18px 20px;
      }

      .product-topline {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 12px;
        margin-bottom: 12px;
      }

      .tag {
        display: inline-flex;
        padding: 6px 10px;
        color: #081006;
        font-size: 0.76rem;
        font-weight: 850;
        border-radius: 999px;
        background: var(--brand);
      }

      .rating {
        color: #fde68a;
        letter-spacing: 0.08em;
      }

      .product-card p,
      .article-card p,
      .deal-card p {
        margin: 10px 0 0;
        color: var(--muted);
      }

      .price-row {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 12px;
        margin-top: 18px;
      }

      .price {
        font-size: 1.3rem;
        font-weight: 850;
      }

      .icon-button {
        display: grid;
        width: 44px;
        height: 44px;
        color: var(--text);
        border: 1px solid var(--line);
        border-radius: 50%;
        background: rgba(255, 255, 255, 0.06);
        cursor: pointer;
        place-items: center;
      }

      .deal-grid {
        grid-template-columns: 1.1fr 0.9fr;
      }

      .deal-card {
        position: relative;
        min-height: 320px;
        overflow: hidden;
        padding: clamp(24px, 4vw, 42px);
      }

      .deal-card.primary {
        background:
          radial-gradient(circle at 72% 45%, rgba(251, 113, 133, 0.34), transparent 16rem),
          linear-gradient(135deg, rgba(245, 158, 11, 0.2), rgba(21, 28, 43, 0.94));
      }

      .deal-card.secondary {
        background:
          radial-gradient(circle at 80% 26%, rgba(34, 211, 238, 0.24), transparent 12rem),
          var(--panel-strong);
      }

      .deal-card h3 {
        max-width: 12ch;
        font-size: clamp(2rem, 4vw, 4.4rem);
      }

      .deal-card p {
        max-width: 46ch;
        margin-bottom: 24px;
      }

      .deal-badge {
        display: inline-flex;
        margin-bottom: 18px;
        padding: 8px 12px;
        color: #170c02;
        font-weight: 900;
        border-radius: 999px;
        background: #fbbf24;
      }

      .countdown {
        display: flex;
        gap: 10px;
        flex-wrap: wrap;
        margin-top: 26px;
      }

      .timebox {
        min-width: 74px;
        padding: 12px;
        text-align: center;
        border: 1px solid var(--line);
        border-radius: 16px;
        background: rgba(0, 0, 0, 0.22);
      }

      .timebox strong {
        display: block;
        font-size: 1.3rem;
      }

      .timebox span {
        color: var(--subtle);
        font-size: 0.77rem;
        text-transform: uppercase;
      }

      .editorial-grid {
        grid-template-columns: 1.2fr 0.8fr 0.8fr;
      }

      .article-card {
        overflow: hidden;
      }

      .article-card.featured {
        grid-row: span 2;
      }

      .article-image {
        min-height: 210px;
        background:
          linear-gradient(135deg, rgba(158, 240, 26, 0.16), rgba(34, 211, 238, 0.18)),
          var(--pattern);
      }

      .article-card.featured .article-image {
        min-height: 390px;
      }

      .article-card h3 {
        margin-top: 8px;
        font-size: clamp(1.25rem, 2vw, 2rem);
        line-height: 1.08;
      }

      .newsletter {
        display: grid;
        grid-template-columns: 1fr auto;
        gap: 24px;
        align-items: center;
        margin: 48px 0 64px;
        padding: clamp(24px, 4vw, 42px);
        background:
          radial-gradient(circle at 85% 40%, rgba(158, 240, 26, 0.18), transparent 18rem),
          var(--panel-strong);
      }

      .newsletter p {
        max-width: 58ch;
        margin: 12px 0 0;
        color: var(--muted);
      }

      .email-form {
        display: flex;
        gap: 10px;
        min-width: min(430px, 100%);
        padding: 8px;
        border: 1px solid var(--line);
        border-radius: 999px;
        background: rgba(0, 0, 0, 0.22);
      }

      .email-form label {
        position: absolute;
        width: 1px;
        height: 1px;
        overflow: hidden;
        clip: rect(0 0 0 0);
        white-space: nowrap;
      }

      .email-form input {
        width: 100%;
        min-height: 46px;
        color: var(--text);
        border: 0;
        background: transparent;
        padding: 0 12px;
        font: inherit;
      }

      .email-form input::placeholder {
        color: var(--subtle);
      }

      .email-form input:focus {
        outline: none;
      }

      .site-footer {
        border-top: 1px solid var(--line);
        color: var(--subtle);
      }

      .footer-inner {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 18px;
        min-height: 92px;
        flex-wrap: wrap;
      }

      @media (max-width: 980px) {
        .hero,
        .deal-grid,
        .newsletter {
          grid-template-columns: 1fr;
        }

        .product-grid,
        .editorial-grid {
          grid-template-columns: repeat(2, minmax(0, 1fr));
        }

        .hero-panel {
          min-height: 460px;
        }

        .nav-links {
          display: none;
        }
      }

      @media (max-width: 640px) {
        .page-shell {
          width: min(100% - 22px, 1180px);
        }

        .nav {
          min-height: 68px;
        }

        .nav-actions .pill {
          display: none;
        }

        .hero {
          padding-top: 28px;
        }

        .hero-copy,
        .deal-card,
        .newsletter {
          padding: 22px;
          border-radius: 22px;
        }

        .hero-panel {
          min-height: 390px;
        }

        .stats,
        .product-grid,
        .editorial-grid {
          grid-template-columns: 1fr;
        }

        .article-card.featured {
          grid-row: auto;
        }

        .article-card.featured .article-image,
        .article-image {
          min-height: 230px;
        }

        .email-form {
          align-items: stretch;
          flex-direction: column;
          border-radius: 22px;
        }

        .email-form .button {
          width: 100%;
        }
      }

      @media (prefers-reduced-motion: no-preference) {
        .product-card,
        .deal-card,
        .article-card,
        .button {
          transition:
            transform 180ms ease,
            border-color 180ms ease,
            box-shadow 180ms ease;
        }

        .product-card:hover,
        .deal-card:hover,
        .article-card:hover {
          border-color: rgba(158, 240, 26, 0.38);
          transform: translateY(-4px);
          box-shadow: 0 24px 70px rgba(0, 0, 0, 0.32);
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main">Skip to main content</a>
    <div id="app"></div>

    <script>
      const products = [
        {
          name: "AeroKnit Commuter Jacket",
          category: "Outerwear",
          description: "Weather-sealed shell with a tailored, city-ready fit.",
          price: "$148",
          rating: "4.9",
          glow: "rgba(34, 211, 238, 0.38)",
          shape: "34% 66% 42% 58%",
        },
        {
          name: "Carbon Trail Runner",
          category: "Footwear",
          description: "Responsive cushioning and all-night reflective details.",
          price: "$132",
          rating: "4.8",
          glow: "rgba(158, 240, 26, 0.34)",
          shape: "58% 42% 48% 52%",
        },
        {
          name: "Modular Sling Pack",
          category: "Accessories",
          description: "Compact storage with magnetic closures and recycled nylon.",
          price: "$86",
          rating: "4.7",
          glow: "rgba(245, 158, 11, 0.34)",
          shape: "24% 24% 44% 44%",
        },
        {
          name: "StudioFlex Utility Pant",
          category: "Apparel",
          description: "Stretch twill, hidden cargo pockets, and a clean taper.",
          price: "$118",
          rating: "4.9",
          glow: "rgba(251, 113, 133, 0.3)",
          shape: "50% 28% 42% 34%",
        },
      ];

      const articles = [
        {
          title: "The new rules of capsule dressing after dark",
          meta: "Style Guide · 6 minute read",
          excerpt:
            "Build a sharper wardrobe with fewer pieces, smarter textures, and versatile midnight palettes.",
          featured: true,
          pattern:
            "repeating-linear-gradient(135deg, #1b2436 0 16px, #111827 16px 32px)",
        },
        {
          title: "How our recycled nylon is tested",
          meta: "Materials · 4 minute read",
          excerpt:
            "Inside the abrasion, water, and colorfastness trials behind our most durable bags.",
          pattern:
            "radial-gradient(circle at 24% 30%, #26344d 0 22%, transparent 23%), linear-gradient(160deg, #121826, #0a0d14)",
        },
        {
          title: "Three ways to style one tech jacket",
          meta: "Editorial · 3 minute read",
          excerpt:
            "From early commute to late dinner, make one performance layer work harder.",
          pattern:
            "linear-gradient(90deg, #0e1726 0 20%, #25324a 20% 22%, #0e1726 22% 44%, #25324a 44% 46%, #0e1726 46%)",
        },
      ];

      function Header() {
        return `
          <header class="site-header" aria-label="Site header">
            <nav class="nav page-shell" aria-label="Primary navigation">
              <a class="brand" href="#" aria-label="Nocturne Supply home">
                <span class="brand-mark" aria-hidden="true">NS</span>
                <span>Nocturne Supply</span>
              </a>
              <div class="nav-links" aria-label="Shopping sections">
                <a href="#featured">Featured</a>
                <a href="#deals">Deals</a>
                <a href="#editorial">Editorial</a>
                <a href="#newsletter">Members</a>
              </div>
              <div class="nav-actions">
                <a class="pill" href="#deals">48-hour drop</a>
                <button class="button" type="button" aria-label="Open shopping bag">Bag (2)</button>
              </div>
            </nav>
          </header>
        `;
      }

      function Hero() {
        return `
          <section class="hero page-shell" aria-labelledby="hero-title">
            <div class="hero-copy">
              <p class="eyebrow">Spring night collection</p>
              <h1 id="hero-title">Retail for the after-hours city.</h1>
              <p>
                Discover elevated everyday gear from technical jackets to sculpted accessories,
                curated for late commutes, weekend escapes, and everything in between.
              </p>
              <div class="hero-actions">
                <a class="button" href="#featured">Shop new arrivals</a>
                <a class="button secondary" href="#editorial">Read the edit</a>
              </div>
              <div class="stats" aria-label="Store highlights">
                <div class="stat"><strong>240+</strong><span>new pieces</span></div>
                <div class="stat"><strong>30%</strong><span>member savings</span></div>
                <div class="stat"><strong>2-day</strong><span>carbon-aware delivery</span></div>
              </div>
            </div>
            <div class="hero-panel" aria-label="Featured Nocturne Supply product display">
              <div class="hero-product" aria-hidden="true"></div>
              <div class="floating-card">
                <strong>Editor pick: AeroKnit Commuter Jacket</strong>
                <span class="kicker">Water resistant · breathable · $148</span>
              </div>
            </div>
          </section>
        `;
      }

      function ProductCard(product) {
        return `
          <article class="product-card">
            <div
              class="product-art"
              style="--glow: ${product.glow}; --shape: ${product.shape};"
              aria-hidden="true"
            >
              <div class="product-shape"></div>
            </div>
            <div class="product-body">
              <div class="product-topline">
                <span class="tag">${product.category}</span>
                <span class="rating" aria-label="${product.rating} out of 5 stars">★ ${product.rating}</span>
              </div>
              <h3>${product.name}</h3>
              <p>${product.description}</p>
              <div class="price-row">
                <span class="price">${product.price}</span>
                <button class="icon-button" type="button" aria-label="Add ${product.name} to bag">+</button>
              </div>
            </div>
          </article>
        `;
      }

      function FeaturedProducts() {
        return `
          <section id="featured" class="page-shell" aria-labelledby="featured-title">
            <div class="section-heading">
              <div>
                <p class="eyebrow">Featured products</p>
                <h2 id="featured-title">Built for motion, styled for night.</h2>
              </div>
              <p>Shop the pieces customers are saving most this week, selected for premium materials and everyday versatility.</p>
            </div>
            <div class="product-grid">
              ${products.map(ProductCard).join("")}
            </div>
          </section>
        `;
      }

      function Deals() {
